// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 balance, uint256 value, address target) public {
        // keep the domain wide: any funded c, any receiver that is a plain EOA-like address,
        // and any requested amount LARGER than c's balance (the low-level call then fails).
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(target != address(this));
        balance = bound(balance, 1, 1e30);
        vm.assume(value > balance);

        vm.deal(address(c), balance);
        uint256 before = address(c).balance;

        // owner is the deployer (this test contract); drive the entry point.
        vm.prank(address(this));
        c.sendMoney(target, value);

        // GENERAL RULE: with value > balance the unchecked low-level call in sendMoney
        // fails silently, so NOTHING leaves c — its balance must be exactly what it was.
        // The mutant sends address(this).balance (which is < value), the call succeeds,
        // and c's balance drops to 0, breaking the rule for every admissible input here.
        assertTrue(address(c).balance == before);
    }
}
